// Verify the local evidence report through the production PagePreview response implementation.
import AppKit
import WebKit
import ClaudeCodeBotCore
final class PreviewSchemeHandler:NSObject,WKURLSchemeHandler {
 static let shared=PreviewSchemeHandler()
 func webView(_ webView:WKWebView,start task:any WKURLSchemeTask){let range=task.request.value(forHTTPHeaderField:"Range");guard let url=task.request.url,let answer=PagePreview.response(for:url,range:range),let response=HTTPURLResponse(url:url,statusCode:answer.statusCode,httpVersion:"HTTP/1.1",headerFields:answer.headers)else{task.didFailWithError(URLError(.fileDoesNotExist));return};task.didReceive(response);task.didReceive(answer.data);task.didFinish()}
 func webView(_ webView:WKWebView,stop task:any WKURLSchemeTask){}
}
@MainActor final class Probe:NSObject,WKScriptMessageHandler{
 let web:WKWebView;let window:NSWindow;var decoded:[[String:Any]]=[];var frame:WKFrameInfo?
 override init(){let config=WKWebViewConfiguration();config.websiteDataStore = .nonPersistent();config.setURLSchemeHandler(PreviewSchemeHandler.shared,forURLScheme:PagePreview.scheme);web=WKWebView(frame:NSRect(x:0,y:0,width:1280,height:1000),configuration:config);window=NSWindow(contentRect:web.frame,styleMask:.borderless,backing:.buffered,defer:false);super.init();window.contentView=web;window.alphaValue=0;window.setFrameOrigin(NSPoint(x:-30000,y:-30000));config.userContentController.add(self,name:"reportDecode");config.userContentController.addUserScript(WKUserScript(source:"window.addEventListener('load',async()=>{const images=[...document.images];if(!images.length)return;await Promise.all(images.map(i=>i.decode().catch(()=>{})));webkit.messageHandlers.reportDecode.postMessage(images.map(i=>({complete:i.complete,width:i.naturalWidth,src:i.src.startsWith('data:image/png;base64,')})))})",injectionTime:.atDocumentEnd,forMainFrameOnly:false))}
 func userContentController(_ userContentController:WKUserContentController,didReceive message:WKScriptMessage){if let result=message.body as? [[String:Any]]{decoded=result;frame=message.frameInfo}}
 func run(_ report:URL,_ output:URL)async throws{var results=[[String:Any]]();for mode in ["window","sandbox"]{decoded=[];frame=nil;let url=mode=="window" ? PagePreview.windowURL(for:report):PagePreview.previewURL(for:report);guard url.scheme=="ccb-preview" else{throw NSError(domain:"Wrong report scheme",code:1)};if mode=="window"{web.load(URLRequest(url:url))}else{web.loadHTMLString("<!doctype html><style>html,body{margin:0;height:100%}iframe{width:100%;height:100%;border:0}</style><iframe sandbox=\"allow-scripts\" src=\"\(url.absoluteString)\"></iframe>",baseURL:nil)};for _ in 0..<100 where decoded.count != 4{try await Task.sleep(for:.milliseconds(50))};guard decoded.count==4,decoded.allSatisfy({$0["complete"] as? Bool==true && ($0["width"] as? Int ?? 0)>0 && $0["src"] as? Bool==true})else{throw NSError(domain:"Decode failed \(mode): \(decoded)",code:2)};for position in ["top","bottom"]{if position=="bottom",let frame{_ = try await web.callAsyncJavaScript("window.scrollTo(0,document.body.scrollHeight);return true",arguments:[:],in:frame,contentWorld:.page)};try await Task.sleep(for:.milliseconds(80));let image=try await web.takeSnapshot(configuration:nil);try NSBitmapImageRep(data:image.tiffRepresentation!)!.representation(using:.png,properties:[:])!.write(to:output.appending(path:"report-\(mode)-\(position).png"))};results.append(["mode":mode,"scheme":url.scheme!,"images":decoded])};try JSONSerialization.data(withJSONObject:results,options:[.prettyPrinted,.sortedKeys]).write(to:output.appending(path:"report-preview-verification.json"));print("PASS: report window + sandbox through production ccb-preview, 4/4 embedded PNGs decoded in each")}
}
@main struct Main{@MainActor static func main(){NSApplication.shared.setActivationPolicy(.prohibited);let probe=Probe();Task{@MainActor in do{try await probe.run(URL(filePath:CommandLine.arguments[1]),URL(filePath:CommandLine.arguments[2]));exit(0)}catch{print("FAIL",error);exit(1)}};NSApplication.shared.run()}}
